{
  "name": "tldr",
  "version": "0.2.7",
  "private": true,
  "type": "module",
  "description": "TLDR — community tl;dr notes for any web page. Monorepo root: canonical shared code + repo-level checks.",
  "license": "MIT",
  "scripts": {
    "build": "npm --prefix extension run build",
    "sync-shared": "node dev/build/tools/sync-shared.mjs",
    "test": "node --test \"shared/test/**/*.test.mjs\" \"dev/build/tools/test/**/*.test.mjs\"",
    "test:all": "npm test && npm --prefix server ci && npm --prefix server test && npm --prefix extension test && npm --prefix dev ci && npm --prefix dev test"
  }
}
---extension/package.json---
{
  "name": "tldr-extension",
  "version": "0.2.7",
  "private": true,
  "type": "module",
  "description": "TLDR Chrome extension (MV3) — side-panel-gated community notes for any web page.",
  "license": "MIT",
  "scripts": {
    "test": "node --test \"../extension-test/**/*.test.mjs\"",
    "build": "node ../dev/build/tools/build-zip.mjs",
    "build:dev": "node ../dev/build/tools/build-zip.mjs dev",
    "build:prod": "node ../dev/build/tools/build-zip.mjs prod"
  }
}
---server/package.json---
{
  "name": "tldr-server",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "TLDR backend — single Lambda behind an HTTP API + JWT authorizer, DynamoDB single table.",
  "license": "MIT",
  "scripts": {
    "test": "node --test \"test/**/*.test.mjs\"",
    "build": "sam build",
    "validate": "sam validate --lint"
  },
  "dependencies": {
    "@aws-sdk/client-dynamodb": "^3.700.0",
    "@aws-sdk/lib-dynamodb": "^3.700.0",
    "ulid": "^2.3.0",
    "esbuild": "^0.24.0"
  },
  "devDependencies": {
    "aws-sdk-client-mock": "^4.1.0"
  }
}
---dev/package.json---
{
  "name": "tldr-dev",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Repo dev tooling: the executable-requirements suite (client UI + server), docs, and build tools.",
  "license": "MIT",
  "scripts": {
    "test": "TZ=UTC LANG=C.UTF-8 node --test \"requirements/**/*.test.mjs\"",
    "test:ui": "TZ=UTC LANG=C.UTF-8 node --test \"requirements/shared/render/dom-snapshots.test.mjs\"",
    "refresh:ui": "TZ=UTC LANG=C.UTF-8 node requirements/shared/render/refresh-snapshots.mjs"
  },
  "devDependencies": {
    "@resvg/resvg-js": "^2.6.2",
    "jsdom": "^29.1.1",
    "pixelmatch": "^7.2.0",
    "pngjs": "^7.0.0",
    "satori": "^0.26.0"
  }
}

